```javascript
function copySchedule() {
  const schedule = WAKE_TIMES.map(([hours, minutes], index) => {
    return `Wake ${String(index + 1).padStart(2, '0')}: ${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')} UTC`;
  }).join('\n');

