  const originalLabel = copyScheduleBtn ? copyScheduleBtn.textContent : '';

  const showFeedback = () => {
    if (copyScheduleBtn) {
      copyScheduleBtn.textContent = 'Copied!';
      setTimeout(() => { copyScheduleBtn.textContent = originalLabel; }, 1500);
    }
  };

  const fallback = () => {
    const ta = document.createElement('textarea');
    ta.value = text;
    ta.style.position = 'fixed';
    ta.style.opacity = '0';
    document.body.appendChild(ta);
    ta.select();
    try { document.execCommand('copy'); } catch (e) {}
    document.body.removeChild(ta);
    showFeedback();
  };

  if (navigator.clipboard && window.isSecureContext) {
    navigator.clipboard.writeText(text).then(showFeedback).catch(fallback);
  } else {
    fallback();
  }
}
```

